package com.careflow.hospital.doctors;
import jakarta.validation.constraints.*; import java.time.Instant; import java.util.UUID;
public final class DoctorDtos {private DoctorDtos(){}public record Apply(@NotBlank @Size(max=160)String fullName,@NotBlank @Size(max=120)String specialization,@NotNull UUID departmentId,@NotBlank @Size(max=2000)String qualifications,@Min(0)@Max(80)int experienceYears,@NotBlank @Size(max=100)String licenseNumber){}public record ApplicationView(UUID applicationId,UUID userId,String fullName,String specialization,UUID departmentId,int experienceYears,String licenseNumber,String status,Instant createdAt){}public record ProfileView(UUID doctorId,String doctorNumber,String fullName,String specialization,UUID departmentId,String departmentName,String licenseNumber,int experienceYears,String verificationStatus,boolean active){}public record Review(@NotBlank @Pattern(regexp="APPROVE|REJECT")String decision){} }
